This question assesses the ability to integrate fetch, WebSocket, and Service Worker into a cohesive offline-first architecture. Key concepts include: offline-first patterns using Service Workers with stale-while-revalidate strategies; WebSocket lifecycle management with exponential backoff reconnection; efficient DOM updates through batched diffing; and maintaining data coherence between REST history and live WebSocket streams.

## Code Example

```javascript
// REST fetch wrapper
async function fetchHistory(id) {
  const res = await fetch(`/api/chat/${id}/history?limit=100`);
  const messages = await res.json();
  await idb.put('chat-db', 'messages', messages);
  return messages;
}

// WebSocket wrapper with reconnection
function createChatSocket(id) {
  const ws = new WebSocket(`/ws/chat/${id}`);
  let reconnectDelay = 1000;

  ws.onclose = () => {
    setTimeout(() => {
      reconnectDelay = Math.min(reconnectDelay * 2, 30000);
      createChatSocket(id);
    }, reconnectDelay);
  };

  ws.onmessage = (e) => handleNewMessage(JSON.parse(e.data));
  return ws;
}

// DOM diff updater
function handleNewMessage(msg) {
  const list = document.getElementById('message-list');
  const existing = Array.from(list.children);
  const newMsgEl = createMessageElement(msg);

  if (!existing.find(el => el.dataset.id === msg.id)) {
    list.appendChild(newMsgEl);
  }
}

// Service Worker caching strategy (stale-while-revalidate)
self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request)
      .then(cached => {
        const fetchPromise = fetch(e.request).then(response => {
          caches.open('chat-v1').then(cache => cache.put(e.request, response.clone()));
          return response;
        });
        return cached || fetchPromise;
      })
  );
});
```

## Purpose
Tests the ability to implement offline-first, real-time collaboration with a patch-based DOM updater and proper sequencing. Covers DOM operations, fetch, WebSocket handling, Service Worker caching, and error handling with reconnection strategies.

## Key Concepts
- Patch-based DOM updates using small, immutable operations
- Per-cell sequencing and out-of-order patch buffering
- Offline-first architecture with Service Worker stale-while-revalidate
- Reconnection strategy with exponential backoff and jitter

## Code Example
```javascript
// REST/WS wrapper with reconnection
class GridClient {
  constructor(url) { this.url = url; this.ws = null; this.seq = {}; }
  async init() {
    const layout = await fetch(this.url + '/grid').then(r => r.json());
    this.render(layout);
    this.connect();
  }
  connect() {
    this.ws = new WebSocket(this.url.replace('http','ws') + '/stream');
    this.ws.onmessage = e => this.process(JSON.parse(e.data));
    this.ws.onclose = () => setTimeout(() => this.connect(), this.backoff());
  }
  backoff() { return Math.min(30000, (this.attempts || 1) * 1000 * (0.5 + Math.random())); }

  // Patch processor with buffering
  process(patch) {
    const { cellId, seq } = patch;
    if (!this.seq[cellId] || seq > this.seq[cellId]) this.pending[cellId]?.push(patch);
    while (this.pending[cellId]?.length) {
      const p = this.pending[cellId].sort((a,b) => a.seq - b.seq).shift();
      if (p.seq === this.seq[cellId] + 1) { this.apply(p); this.seq[cellId] = p.seq; }
    }
  }
  apply({cellId, op, value}) {
    const el = document.getElementById(cellId);
    if (op === 'set') el.textContent = value;
    else if (op === 'add') el.insertAdjacentHTML('beforeend', value);
    else if (op === 'del') el.remove();
  }
}
```

## Why This Is Asked
This question evaluates advanced JavaScript patterns including per-key caching, Promise deduplication, TTL-based eviction, and reactive update patterns commonly needed in frontend applications.

## Key Concepts
- **Closures and per-key maps**: Isolated state management for each cached key
- **Promise deduplication**: Avoiding redundant network requests for concurrent loads of the same key
- **TTL-based eviction**: Time-to-live expiration for cache entries
- **Change notifications**: Listener pattern for broadcasting data updates
- **Error handling**: Graceful handling of fetch failures and cache misses

## Code Example
```javascript
function createDataLoader(fetchFn, ttlMs) {
  const cache = new Map();

  function getEntry(key) {
    if (!cache.has(key)) {
      cache.set(key, { promise: null, data: null, expiry: 0, listeners: [] });
    }
    return cache.get(key);
  }

  const notify = (key, data, error) => {
    const entry = cache.get(key);
    if (entry?.listeners.length) {
      entry.listeners.forEach(cb => cb(data, error));
    }
  };

  return {
    load(key) {
      const entry = getEntry(key);
      const now = Date.now();

      if (entry.data && entry.expiry > now) {
        return Promise.resolve(entry.data);
      }

      if (entry.promise) {
        return entry.promise;
      }

      entry.promise = fetchFn(key)
        .then(data => {
          entry.data = data;
          entry.expiry = now + ttlMs;
          entry.promise = null;
          notify(key, data, null);
          return data;
        })
        .catch(err => {
          entry.promise = null;
          notify(key, null, err);
          throw err;
        });

      return entry.promise;
    },

    invalidate(key) {
      const entry = cache.get(key);
      if (entry) {
        entry.data = null;
        entry.expiry = 0;
        entry.promise = null;
      }
    },

    onChange(key, cb) {
      const entry = getEntry(key);
      entry.listeners.push(cb);
      return () => {
        entry.listeners = entry.listeners.filter(l => l !== cb);
      };
    }
  };
}
```

## Usage Example
```javascript
const loader = createDataLoader(fetchUser, 5000);

// Two different keys
loader.onChange('user:1', (data) => console.log('User 1 updated:', data));
loader.onChange('user:2', (data) => console.log('User 2 updated:', data));

// Concurrent loads for same key are deduplicated
loader.load('user:1').then(console.log);
loader.load('user:1').then(console.log); // Reuses in-flight request

// Invalidate and reload
loader.invalidate('user:1');
loader.load('user:1');
```

## Eviction Strategies
- **TTL-based**: Automatic expiration after ttlMs (implemented above)
- **LRU**: Evict least recently used entries when cache size exceeds limit
- **Manual**: Explicit invalidate() calls

## Error Handling
- Failed fetches propagate errors to all waiters via rejected Promise
- Listeners receive error state for reactive UI updates
- In-flight promises are cleared on error to allow retries

