// Dynamic import for analytics chart
const HeavyChart = React.lazy(() => import('./charts/HeavyChart'));

// Visibility gate wrapper
function useVisible(ref) {
  const [visible, setVisible] = React.useState(false);
  React.useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setVisible(entry.isIntersecting),
      { threshold: 0.1 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref]);
  return visible;
}
```

## Why This Is Asked
Tests the ability to coordinate streaming fetch, WebSocket connections, and DOM diffing without a framework, while properly managing lifecycles and service worker interactions.

## Key Concepts
- Streaming fetch with ReadableStream and NDJSON parsing
- WebSocket-based real-time updates per tenant
- Lightweight DOM diffing with batched rendering
- Service Worker cache with stale-while-revalidate strategy for streaming data
- Proper cleanup on tenant switch and navigation

## Code Example

```javascript
async function bootstrapInit(tenant) {
  const r = await fetch(`/init?tenantId=${tenant}`);
  const reader = r.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split('\n');
    buffer = lines.pop();

    for (const line of lines) {
      if (line) yield JSON.parse(line);
    }
  }
}
```

## Why This Is Asked

Tests ability to use closures for private state, manage asynchronous fetches with Promises, and implement simple caching and de-duplication without a framework.

## Key Concepts

- Closures for private state (cache and inFlight)
- Promises and in-flight request deduplication
- Time-based cache TTL (10s)
- Robust fetch error handling and URL composition

## Code Example

```javascript
function createLoader(baseUrl) {
  const cache = new Map();
  const inFlight = new Map();

  const join = (p) => {
    if (baseUrl.endsWith('/') || p.startsWith('/')) return `${baseUrl}${p}`;
    return `${baseUrl}/${p}`;
  };

  return {
    load(path) {
      const url = join(path);
      return fetch(url).then(r => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      });
    },

    cachedLoad(path) {
      const key = path;
      const ttl = 10000; // 10 seconds
      const now = Date.now();
      const cached = cache.get(key);
      if (cached && now - cached.t < ttl) return Promise.resolve(cached.v);

      if (inFlight.has(key)) return inFlight.get(key);

      const url = join(path);
      const p = fetch(url).then(r => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      }).then(v => {
        cache.set(key, { t: Date.now(), v });
        inFlight.delete(key);
        return v;
      }).catch(e => {
        inFlight.delete(key);
        throw e;
      });

      inFlight.set(key, p);
      return p;
    }
  };
}
```

