## Why This Is Asked

This question tests mastery of closures, promises, and per-key caching with real-world constraints like deduplicating in-flight requests, enforcing concurrency limits, and implementing TTL-based invalidation.

## Key Concepts

- **Closures and per-key cache state**: Using closures to maintain cache and in-flight maps private to each loader instance
- **In-flight deduplication**: Sharing promises for concurrent requests to the same key to prevent redundant fetches
- **Concurrency control**: Implementing a semaphore pattern with a 3-request cap
- **TTL-based caching**: Storing expiration timestamps and evicting stale entries
- **Background refresh**: Silently refetching expired keys without blocking callers
- **Invalidation semantics**: Manual cache invalidation for real-time scenarios

## Code Example

```javascript
function createResourceLoader(fetcher) {
  const cache = new Map();
  const inFlight = new Map();
  let active = 0;
  const maxConcurrent = 3;
  const waiting = [];

  const acquire = () => new Promise(resolve => {
    if (active < maxConcurrent) {
      active++;
      resolve();
    } else {
      waiting.push(resolve);
    }
  });

  const release = () => {
    if (waiting.length > 0) {
      waiting.shift()();
    } else {
      active--;
    }
  };

  return {
    load(key, ttl = 5000) {
      const cached = cache.get(key);
      const now = Date.now();

      if (cached) {
        if (cached.expiry > now) {
          return cached.value;
        }
        if (!inFlight.has(key)) {
          fetcher(key).then(value => {
            cache.set(key, { value, expiry: Date.now() + ttl });
          });
        }
      }

      if (inFlight.has(key)) {
        return inFlight.get(key);
      }

      const promise = acquire().then(async () => {
        try {
          const value = await fetcher(key);
          cache.set(key, { value, expiry: Date.now() + ttl });
          return value;
        } finally {
          release();
          inFlight.delete(key);
        }
      });

      inFlight.set(key, promise);
      return promise;
    },

    invalidate(key) {
      cache.delete(key);
    }
  };
}

// Mock fetcher
const fetchUser = createResourceLoader(async (id) => {
  console.log(`Fetching user ${id}...`);
  await new Promise(r => setTimeout(r, 100));
  return { id, name: `User ${id}` };
});

// Usage
await fetchUser.load('user:1', 2000);
await fetchUser.load('user:1'); // Uses cache
fetchUser.invalidate('user:1');
await fetchUser.load('user:1'); // Refetches
```

## Why This Is Asked
Tests mastery of closures, promise sharing, and robust batching logic in the UI. It probes how a candidate handles in-flight deduping, race conditions, and cache invalidation in a realistic data-fetching utility.

## Key Concepts
- Closures to encapsulate private state (inFlight, cache, batch)
- Shared Promises for identical keys to prevent duplicate fetches
- Debounced batching with batchDelay and maxBatchSize
- Cache population and correct mapping from response to keys
- Error handling and late responses without memory leaks

## Code Example
```javascript
function createBatcher(fetchFn, { batchDelay = 50, maxBatchSize = 20 } = {}) {
  const cache = new Map();
  const inFlight = new Map();
  let batch = new Set();
  let timer = null;

  function flush() {
    const keys = Array.from(batch).slice(0, maxBatchSize);
    batch.clear();
    timer = null;
    if (keys.length === 0) return;
    const p = fetchFn(keys);
    keys.forEach(k => inFlight.delete(k));
    p.then(res => {
      keys.forEach(k => {
        if (res.hasOwnProperty(k)) {
          cache.set(k, res[k]);
          const { resolve } = inFlight.get(k) || {};
          if (resolve) resolve(res[k]);
          inFlight.delete(k);
        }
      });
    }).catch(err => {
      keys.forEach(k => {
        const { reject } = inFlight.get(k) || {};
        if (reject) reject(err);
        inFlight.delete(k);
      });
    });
  }

  function enqueue(key) {
    if (cache.has(key)) return Promise.resolve(cache.get(key));
    if (inFlight.has(key)) return inFlight.get(key).promise;

    let resolve, reject;
    const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
    inFlight.set(key, { promise, resolve, reject });
    batch.add(key);

    if (!timer) timer = setTimeout(flush, batchDelay);
    return promise;
  }

  return {
    get: (key) => enqueue(key),
    clearCache: () => cache.clear(),
  };
}
```

